const s=require('../../../../miniprogram/utils/service'),d=require('../../../../miniprogram/utils/domain');Page({data:{week:d.weekKey(),busy:false,error:'',lines:[],extra:'',notes:{},version:0,plan:null,role:'',loaded:false},onLoad(o){if(o.week)this.setData({week:o.week});},onShow(){this.load();},async load(){await s.run(this,async()=>{const c=await s.call();if(c.unbound)throw Error('先到“我们”创建或加入家庭');const p=c.state.plans[this.data.week];const draft=s.draft(this.data.week);const counts=draft?draft.counts:Object.fromEntries((p?p.lines:[]).map(l=>[l.id,l.count]));const notes=draft&&draft.notes||Object.fromEntries((p?p.lines:[]).map(l=>[l.id,l.note]));const options=draft&&draft.options||Object.fromEntries((p?p.lines:[]).map(l=>[l.id,{spice:l.spice||'不辣',servings:l.servings||1}]));const coverage=d.coverage(c.state.recipes,Object.entries(counts).map(([id,count])=>({id,count})));const extra=draft&&Object.hasOwn(draft,'extra')?draft.extra:p?p.extra:'';this.setData({loaded:true,role:c.role,plan:p||null,version:p?p.version:0,extra,notes,counts,options,coverage,lines:c.state.recipes.filter(r=>counts[r.id]>0).map(r=>({...r,count:counts[r.id],spice:(options[r.id]||{}).spice||'不辣',servings:(options[r.id]||{}).servings||1,note:notes[r.id]||''}))});});},onPullDownRefresh(){this.load().finally(()=>wx.stopPullDownRefresh());},changeWeek(e){this.setData({week:e.detail.value});this.load();},note(e){const notes={...this.data.notes,[e.currentTarget.dataset.id]:e.detail.value};this.setData({notes});this.save();},extra(e){this.setData({extra:e.detail.value});this.save();},save(){s.saveDraft(this.data.week,{counts:this.data.counts||{},notes:this.data.notes,options:this.data.options,extra:this.data.extra});},submit(){return s.run(this,async()=>{if(!this.requestId)this.requestId=Date.now()+'-'+Math.random().toString(16).slice(2);await s.call('submit',{week:this.data.week,lines:this.data.lines.map(l=>({id:l.id,count:l.count,spice:l.spice,servings:l.servings,note:this.data.notes[l.id]||''})),extra:this.data.extra,expectedVersion:this.data.version,requestId:this.requestId});s.clearDraft(this.data.week);this.requestId=null;wx.showToast({title:'菜单已提交',icon:'success'});});},async confirm(){await s.run(this,async()=>{await s.call('confirm',{week:this.data.week,version:this.data.version});wx.showToast({title:'收到啦',icon:'success'});});await this.load();},async submitted(){await this.submit();await this.load();},menu(){wx.switchTab({url:'/pages/menu/index'});},history(){wx.navigateTo({url:'/pages/history/index'});},async subscribe(){await s.run(this,async()=>{await s.subscribe();wx.showToast({title:'已处理订阅选择',icon:'none'});});}});